insert into public.assessment_questions (category, ref, text_en, text_cy, sort) values
('registration','R1','The practice''s HIW registration certificate and statement of purpose are current and on display.','Mae tystysgrif cofrestru HIW y practis a''r datganiad o ddiben yn gyfredol ac wedi''u harddangos.',1),
('registration','R2','Registered manager and responsible individual details are up to date with HIW.','Mae manylion y rheolwr cofrestredig a''r unigolyn cyfrifol yn gyfredol gyda HIW.',2),
('registration','R3','Public and employer''s liability insurance certificates are in date.','Mae tystysgrifau yswiriant atebolrwydd cyhoeddus ac atebolrwydd cyflogwr o fewn eu dyddiad.',3),
('registration','R4','The annual HIW registration fee is paid and notifications of changes have been submitted.','Mae ffi gofrestru flynyddol HIW wedi''i thalu ac mae hysbysiadau o newidiadau wedi''u cyflwyno.',4),

('staff_training','T1','Every staff member has a complete pre-employment file (references, employment history, right to work).','Mae gan bob aelod o staff ffeil cyn-cyflogaeth gyflawn (geirdaon, hanes cyflogaeth, hawl i weithio).',5),
('staff_training','T2','Enhanced DBS checks are in place and recorded for all staff who need them.','Mae gwiriadau DBS uwch ar waith ac wedi''u cofnodi ar gyfer yr holl staff sydd eu hangen.',6),
('staff_training','T3','All staff have completed a structured induction, signed off by a manager.','Mae pob aelod o staff wedi cwblhau sefydlu strwythuredig, wedi''i lofnodi gan reolwr.',7),
('staff_training','T4','Mandatory training (basic life support, safeguarding, infection control) is in date for all staff.','Mae hyfforddiant gorfodol (cymorth cyntaf sylfaenol, diogelu, rheoli haint) o fewn dyddiad i''r holl staff.',8),

('decontamination','D1','Decontamination procedures follow WHTM 01-05 and are documented.','Mae gweithdrefnau diheintio yn dilyn WHTM 01-05 ac wedi''u dogfennu.',9),
('decontamination','D2','Autoclave and washer-disinfector daily, weekly and periodic test records are complete.','Mae cofnodion profion dyddiol, wythnosol ac cyfnodol yr awtoclaf a''r golchwr-diheintydd yn gyflawn.',10),
('decontamination','D3','A named decontamination lead is in place and trained.','Mae arweinydd diheintio a enwir ar waith ac wedi''i hyfforddi.',11),
('decontamination','D4','Validation and servicing certificates for decontamination equipment are in date.','Mae tystysgrifau dilysu a gwasanaethu ar gyfer offer diheintio o fewn eu dyddiad.',12),

('radiation','X1','A radiation protection advisor (RPA) and supervisor are appointed, with written local rules.','Mae cynghorydd diogelu rhag ymbelydredd (RPA) a goruchwyliwr wedi''u penodi, gyda rheolau lleol ysgrifenedig.',13),
('radiation','X2','X-ray equipment critical examination, acceptance and routine test records are in date.','Mae cofnodion archwiliad critigol, derbyn a phrofion arferol offer pelydr-X o fewn eu dyddiad.',14),
('radiation','X3','IR(ME)R employer''s procedures and protocols are in place and reviewed.','Mae gweithdrefnau a phrotocolau cyflogwr IR(ME)R ar waith ac wedi''u hadolygu.',15),
('radiation','X4','Staff entitled under IR(ME)R have documented training and entitlement.','Mae gan staff sydd â hawl o dan IR(ME)R hyfforddiant a hawl wedi''u dogfennu.',16),

('health_safety','H1','Fire risk assessment, alarm tests and evacuation drills are recorded and in date.','Mae asesiad risg tân, profion larwm a driliau gwacáu wedi''u cofnodi ac o fewn eu dyddiad.',17),
('health_safety','H2','Electrical (fixed wire and PAT) and gas safety certificates are in date.','Mae tystysgrifau diogelwch trydanol (gwifrau sefydlog a PAT) a nwy o fewn eu dyddiad.',18),
('health_safety','H3','COSHH, legionella and general risk assessments are completed and reviewed.','Mae asesiadau risg COSHH, legionella ac asesiadau risg cyffredinol wedi''u cwblhau a''u hadolygu.',19),
('health_safety','H4','An accident and incident reporting process is in place and staff know how to use it.','Mae proses adrodd ar ddamweiniau a digwyddiadau ar waith ac mae staff yn gwybod sut i''w defnyddio.',20),

('policies','P1','Core policies (safeguarding, complaints, infection control, data protection) are current and reviewed annually.','Mae polisïau craidd (diogelu, cwynion, rheoli haint, diogelu data) yn gyfredol ac yn cael eu hadolygu''n flynyddol.',21),
('policies','P2','A complaints procedure is displayed and complaints are logged and learned from.','Mae gweithdrefn gwyno wedi''i harddangos ac mae cwynion yn cael eu cofnodi a''u dysgu ohonynt.',22),
('policies','P3','Patient feedback is collected and acted on.','Mae adborth cleifion yn cael ei gasglu a''i weithredu arno.',23),
('policies','P4','Business continuity and emergency (medical emergency, drugs and equipment) plans are in place.','Mae cynlluniau parhad busnes ac argyfwng (argyfwng meddygol, cyffuriau ac offer) ar waith.',24);

